822	    /**
823	     * Change the note type from oldModel to newModel, handling the case where a full sync will be required
824	     */
825	    private void changeNoteTypeWithErrorHandling(final JSONObject oldModel, final JSONObject newModel) {
826	        Resources res = getResources();
827	        try {
828	            changeNoteType(oldModel, newModel);
829	        } catch (ConfirmModSchemaException e) {
830	            // Libanki has determined we should ask the user to confirm first
831	            ConfirmationDialog dialog = new ConfirmationDialog();
832	            dialog.setArgs(res.getString(R.string.full_sync_confirmation));
833	            Runnable confirm = () -> {
834	                // Bypass the check once the user confirms
835	                getCol().modSchemaNoCheck();
836	                try {
837	                    changeNoteType(oldModel, newModel);
838	                } catch (ConfirmModSchemaException e2) {
839	                    // This should never be reached as we explicitly called modSchemaNoCheck()
840	                    throw new RuntimeException(e2);
841	                }
842	            };
843	            dialog.setConfirm(confirm);
844	            showDialogFragment(dialog);
845	        }
846	    }
