852	    private void changeNoteType(JSONObject oldModel, JSONObject newModel) throws ConfirmModSchemaException {
853	        final long [] nids = {mEditorNote.getId()};
854	        getCol().getModels().change(oldModel, nids, newModel, mModelChangeFieldMap, mModelChangeCardMap);
855	        // refresh the note object to reflect the database changes
