1243	    private void searchCards() {
1244	        // cancel the previous search & render tasks if still running
1245	        CollectionTask.cancelTask(CollectionTask.TASK_TYPE_SEARCH_CARDS);
1246	        CollectionTask.cancelTask(CollectionTask.TASK_TYPE_RENDER_BROWSER_QA);
1247	        String searchText;
1248	        if (mSearchTerms == null) {
1249	            mSearchTerms = "";
1250	        }
1251	        if (!"".equals(mSearchTerms) && (mSearchView != null)) {
1252	            mSearchView.setQuery(mSearchTerms, false);
1253	            mSearchItem.expandActionView();
1254	        }
1255	        if (mSearchTerms.contains("deck:")) {
1256	            searchText = mSearchTerms;
1257	        } else {
1258	            searchText = mRestrictOnDeck + mSearchTerms;
1259	        }
1260	        if (colIsOpen() && mCardsAdapter!= null) {
1261	            // clear the existing card list
1262	            mCards = new ArrayList<Map<String, String>>();
1263	            mCardsAdapter.notifyDataSetChanged();
1264	            //  estimate maximum number of cards that could be visible (assuming worst-case minimum row height of 20dp)
1265	            int numCardsToRender = (int) Math.ceil(mCardsListView.getHeight()/
1266	                    TypedValue.applyDimension(TypedValue.COMPLEX_UNIT_DIP, 20, getResources().getDisplayMetrics())) + 5;
1267	            // Perform database query to get all card ids
1268	            CollectionTask.launchCollectionTask(CollectionTask.TASK_TYPE_SEARCH_CARDS, mSearchCardsHandler, new CollectionTask.TaskData(
1269	                    new Object[] {searchText, ((mOrder != CARD_ORDER_NONE)),  numCardsToRender}));
1270	        }
