1336	    private void filterByTag(List<String> selectedTags, int option) {
1337	        //TODO: Duplication between here and CustomStudyDialog:customStudyFromTags
1338	        mSearchView.setQuery("", false);
1339	        String tags = selectedTags.toString();
1340	        mSearchView.setQueryHint(getResources().getString(R.string.card_browser_tags_shown,
1341	                tags.substring(1, tags.length() - 1)));
1342	        StringBuilder sb = new StringBuilder();
1343	        switch (option) {
1344	            case 1:
1345	                sb.append("is:new ");
1346	                break;
1347	            case 2:
1348	                sb.append("is:due ");
1349	                break;
1350	            default:
1351	                // Logging here might be appropriate : )
1352	                break;
1353	        }
1354	        int i = 0;
1355	        for (String tag : selectedTags) {
1356	            if (i != 0) {
1357	                sb.append("or ");
1358	            } else {
1359	                sb.append("("); // Only if we really have selected tags
1360	            }
1361	            sb.append("tag:").append(tag).append(" ");
1362	            i++;
1363	        }
1364	        if (i > 0) {
1365	            sb.append(")"); // Only if we added anything to the tag list
1366	        }
1367	        mSearchTerms = sb.toString();
1368	        searchCards();
1369	    }
