private long[] getSelectedCardIds() {
    //copy to array to ensure threadsafe iteration
    Integer[] checkedPositions = mCheckedCardPositions.toArray(new Integer[0]);
    //copy the reference: the list can be replaced by an async operation while we iterate
    List<Map<String, String>> cards = getCards();
    long[] ids = new long[checkedPositions.length];
    int count = 0;
    for (int cardPosition : checkedPositions) {
        //#6112: A checked position refers to the card list which was displayed when the card was checked.
        //If the list was reloaded (or cleared) in the meantime, the position may no longer be valid.
        if (cardPosition < 0 || cardPosition >= cards.size()) {
            Timber.w("Attempted to access card at invalid position: %d (%d cards)", cardPosition, cards.size());
            continue;
        }
        String cardId = cards.get(cardPosition).get(ID);
        if (cardId == null) {
            Timber.w("No card id at position: %d", cardPosition);
            continue;
        }
        ids[count++] = Long.parseLong(cardId);
    }
    //the array may have been oversized if some positions were stale
    if (count != ids.length) {
        ids = Arrays.copyOf(ids, count);
    }
    return ids;
}

/**
 * @return Whether the currently selected cards all belong to one (and only one) note.
 * Used to determine whether the note can be edited: editing only affects a single note (#6112),
 * so we must not offer the option when cards of multiple notes are selected.
 */
private boolean hasSelectedSingleNoteId() {
    long[] selectedCardIds = getSelectedCardIds();
    if (selectedCardIds.length == 0) {
        return false;
    }
    if (selectedCardIds.length == 1) {
        //one card is always exactly one note: no need to hit the database
        return true;
    }
    //Heuristic to skip a potentially large query
    if (selectedCardIds.length > 50) {
        return false;
    }
    if (!colIsOpen()) {
        return false;
    }
    try {
        //Note: the "note" column of the browser contains the note type name, not the note id,
        //so the selected note ids have to be obtained from the collection.
        int noteCount = getCol().getDb().queryScalar(
                "select count(distinct nid) from cards where id in " + Utils.ids2str(selectedCardIds));
        return noteCount == 1;
    } catch (Exception e) {
        Timber.w(e, "Failed to determine the number of selected notes");
        return false;
    }
}

