private void onSelectNone() {
    mCheckedCardPositions.clear();
    onSelectionChanged();
}

/**
 * Removes the current selection (and exits multi-select mode).
 *
 * The selection is stored as a list of positions inside the currently displayed card list, so it becomes
 * meaningless as soon as that list is reloaded: the positions then either refer to different cards, or
 * to cards which no longer exist (which previously caused an {@link IndexOutOfBoundsException}: #6112).
 */
private void invalidateSelection() {
    if (mCheckedCardPositions.isEmpty()) {
        return;
    }
    Timber.d("invalidateSelection() - the card list was reloaded, clearing the selection");
    onSelectNone();
}

