public void editNoteIsNotAvailableWhenCardsOfMultipleNotesAreSelected() {
    //#6112 - "note" is the note type name, so two notes of the same note type were previously
    //seen as a single note, the note editor was displayed, and only the first note was modified.
    CardBrowser b = getBrowserWithNotes(2);

    b.checkedCardsAtPositions(new int[] {0, 1});

    assertThat("Two notes are selected", b.checkedCardCount(), is(2));
    assertThat("Editing a note only affects a single note, so should not be offered",
            b.isShowingEditNote(), is(false));
}

