    assertThat("A single note is selected", b.checkedCardCount(), is(1));
    assertThat("Editing a single note should be offered", b.isShowingEditNote(), is(true));
}

@Test
public void selectionIsRemovedWhenTheCardListIsReloaded() {
    //#6112 - the selection is a list of positions in the card list. Once the list is reloaded
    //(for example after the note type of a note was changed in the note editor), the positions
    //no longer refer to the same cards, and using them crashed the browser.
    CardBrowser b = getBrowserWithNotes(3);
    b.checkedCardsAtPositions(new int[] {0, 1});

    AnkiAssert.assertDoesNotThrow(b::searchCards);

    assertThat("The stale selection should have been removed", b.checkedCardCount(), is(0));
    assertThat("Multi-select mode should have ended", b.isInMultiSelectMode(), is(false));
    AnkiAssert.assertDoesNotThrow(b::getCheckedCardIds);
}

