852	    private void _changeNotes(long[] nids, JSONObject newModel, Map<Integer, Integer> map) {
853	        List<Object[]> d = new ArrayList<>();
854	        int nfields;
855	        long mid;
856	        nfields = newModel.getJSONArray("flds").length();
857	        mid = newModel.getLong("id");
858	        try (Cursor cur = mCol.getDb().getDatabase().query(
859	                "select id, flds from notes where id in ".concat(Utils.ids2str(nids)), null)) {
860	            while (cur.moveToNext()) {
861	                long nid = cur.getLong(0);
862	                String[] flds = Utils.splitFields(cur.getString(1));
863	                Map<Integer, String> newflds = new HashMap<>();
864	
865	                for (Integer old : map.keySet()) {
866	                    newflds.put(map.get(old), flds[old]);
867	                }
868	                List<String> flds2 = new ArrayList<>();
869	                for (int c = 0; c < nfields; ++c) {
870	                    if (newflds.containsKey(c)) {
871	                        flds2.add(newflds.get(c));
872	                    } else {
873	                        flds2.add("");
874	                    }
875	                }
876	                String joinedFlds = Utils.joinFields(flds2.toArray(new String[flds2.size()]));
877	                d.add(new Object[] { joinedFlds, mid, Utils.intTime(), mCol.usn(), nid });
878	            }
879	        }
880	        mCol.getDb().executeMany("update notes set flds=?,mid=?,mod=?,usn=? where id = ?", d);
881	        mCol.updateFieldCache(nids);
882	    }
