736	    void saveNote() {
737	        final Resources res = getResources();
738	        if (mSelectedTags == null) {
739	            mSelectedTags = new ArrayList<>();
740	        }
741	        // treat add new note and edit existing note independently
742	        if (mAddNote) {
743	            //Different from libAnki, block if there are no cloze deletions.
744	            //DEFECT: This does not block addition if cloze transpositions are in non-cloze fields.
745	            if (isClozeType() && !hasClozeDeletions()) {
746	                displayErrorSavingNote();
747	                return;
748	            }
749	
750	            // load all of the fields into the note
751	            for (FieldEditText f : mEditFields) {
752	                updateField(f);
753	            }
754	            // Save deck to model
755	            mEditorNote.model().put("did", mCurrentDid);
756	            // Save tags to model
757	            mEditorNote.setTagsFromStr(tagsAsString(mSelectedTags));
758	            JSONArray ja = new JSONArray();
759	            for (String t : mSelectedTags) {
760	                ja.put(t);
761	            }
762	            getCol().getModels().current().put("tags", ja);
763	            getCol().getModels().setChanged();
764	            CollectionTask.launchCollectionTask(CollectionTask.TASK_TYPE_ADD_NOTE, mSaveNoteHandler, new CollectionTask.TaskData(mEditorNote));
765	        } else {
766	            // Check whether note type has been changed
767	            final JSONObject newModel = getCurrentlySelectedModel();
768	            final JSONObject oldModel = mCurrentEditedCard.model();
769	            if (!newModel.equals(oldModel)) {
770	                mReloadRequired = true;
771	                if (mModelChangeCardMap.size() < mEditorNote.cards().size() || mModelChangeCardMap.containsKey(null)) {
772	                    // If cards will be lost via the new mapping then show a confirmation dialog before proceeding with the change
773	                    ConfirmationDialog dialog = new ConfirmationDialog ();
774	                    dialog.setArgs(res.getString(R.string.confirm_map_cards_to_nothing));
775	                    Runnable confirm = () -> {
776	                        // Bypass the check once the user confirms
777	                        changeNoteTypeWithErrorHandling(oldModel, newModel);
778	                    };
779	                    dialog.setConfirm(confirm);
780	                    showDialogFragment(dialog);
781	                } else {
782	                    // Otherwise go straight to changing note type
783	                    changeNoteTypeWithErrorHandling(oldModel, newModel);
784	                }
785	                return;
786	            }
787	            // Regular changes in note content
788	            boolean modified = false;
789	            // changed did? this has to be done first as remFromDyn() involves a direct write to the database
790	            if (mCurrentEditedCard.getDid() != mCurrentDid) {
791	                mReloadRequired = true;
792	                // remove card from filtered deck first (if relevant)
793	                getCol().getSched().remFromDyn(new long[] { mCurrentEditedCard.getId() });
794	                // refresh the card object to reflect the database changes in remFromDyn()
795	                mCurrentEditedCard.load();
796	                // also reload the note object
797	                mEditorNote = mCurrentEditedCard.note();
798	                // then set the card ID to the new deck
799	                mCurrentEditedCard.setDid(mCurrentDid);
800	                modified = true;
801	            }
802	            // now load any changes to the fields from the form
803	            for (FieldEditText f : mEditFields) {
804	                modified = modified | updateField(f);
805	            }
806	            // added tag?
807	            for (String t : mSelectedTags) {
808	                modified = modified || !mEditorNote.hasTag(t);
809	            }
810	            // removed tag?
811	            modified = modified || mEditorNote.getTags().size() > mSelectedTags.size();
812	            if (modified) {
813	                mEditorNote.setTagsFromStr(tagsAsString(mSelectedTags));
814	                // set a flag so that changes to card object will be written to DB later via onActivityResult() in
815	                // CardBrowser
816	                mChanged = true;
817	            }
